// Ported from the Node app's Sequelize model StaffUnavailability (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StaffUnavailabilityConfiguration : IEntityTypeConfiguration<StaffUnavailability>
{
    public void Configure(EntityTypeBuilder<StaffUnavailability> builder)
    {
        builder.ToTable("staff_unavailability");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.Day).HasColumnName("day");
        builder.Property(e => e.Period).HasColumnName("period");
        builder.HasIndex(e => new { e.StaffId, e.Day, e.Period }).IsUnique().HasDatabaseName("uq_staff_unavail");
        builder.HasOne(e => e.Staff).WithMany(p => p.StaffUnavailabilities).HasForeignKey(e => e.StaffId).OnDelete(DeleteBehavior.NoAction);
    }
}
